import { useMemo, useState } from 'react';
import { JxButton, JxInputField, JxStepper } from '@jinx-ui/react';

export interface RegistrationValues {
  name: string;
  email: string;
  phone: string;
  city: string;
  street: string;
  zip: string;
}

interface FieldConfig {
  name: keyof RegistrationValues;
  label: string;
  type?: string;
  prefix?: string;
  helperText?: string;
  validate: (value: string) => string | undefined;
}

const required = (value: string) => (value.trim() ? undefined : 'Заполните поле');

const STEP_FIELDS: FieldConfig[][] = [
  [
    { name: 'name', label: 'Имя и фамилия', validate: required },
    {
      name: 'email',
      label: 'Электронная почта',
      type: 'email',
      validate: (value) =>
        !value.trim() ? 'Заполните поле' : value.includes('@') ? undefined : 'Укажите адрес с символом @',
    },
    {
      name: 'phone',
      label: 'Телефон',
      type: 'tel',
      prefix: '+7',
      helperText: '10 цифр без пробелов',
      validate: (value) =>
        !value.trim() ? 'Заполните поле' : /^\d{10}$/.test(value.trim()) ? undefined : 'Нужно ровно 10 цифр',
    },
  ],
  [
    { name: 'city', label: 'Город', validate: required },
    { name: 'street', label: 'Улица, дом, квартира', validate: required },
    {
      name: 'zip',
      label: 'Почтовый индекс',
      validate: (value) =>
        !value.trim() ? 'Заполните поле' : /^\d{6}$/.test(value.trim()) ? undefined : 'Индекс из 6 цифр',
    },
  ],
];

const EMPTY: RegistrationValues = { name: '', email: '', phone: '', city: '', street: '', zip: '' };

export default function RegistrationWizard({
  onSubmit,
}: {
  onSubmit: (values: RegistrationValues) => void | Promise<void>;
}) {
  const [step, setStep] = useState(0);
  const [values, setValues] = useState<RegistrationValues>(EMPTY);
  const [showErrors, setShowErrors] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [submitError, setSubmitError] = useState<string | undefined>(undefined);

  const isLast = step === 2;

  const stepErrors = useMemo(() => {
    const fields = STEP_FIELDS[step] ?? [];
    return fields.reduce<Partial<Record<keyof RegistrationValues, string>>>((acc, field) => {
      const message = field.validate(values[field.name]);
      if (message) acc[field.name] = message;
      return acc;
    }, {});
  }, [step, values]);

  const change = (name: keyof RegistrationValues) => (event: React.ChangeEvent<HTMLInputElement>) => {
    const next = event.target.value;
    setValues((prev) => ({ ...prev, [name]: next }));
  };

  const goBack = () => {
    setSubmitError(undefined);
    setShowErrors(false);
    setStep((prev) => Math.max(prev - 1, 0));
  };

  const handleSubmit = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (submitting) return;

    if (!isLast) {
      if (Object.keys(stepErrors).length > 0) {
        setShowErrors(true);
        return;
      }
      setShowErrors(false);
      setStep((prev) => prev + 1);
      return;
    }

    setSubmitError(undefined);
    setSubmitting(true);
    try {
      await onSubmit(values);
    } catch {
      setSubmitError('Не удалось отправить анкету. Проверьте соединение и попробуйте ещё раз.');
    } finally {
      setSubmitting(false);
    }
  };

  const reviewRows = STEP_FIELDS.flat().map((field) => ({
    label: field.label,
    value: values[field.name].trim() ? `${field.prefix ?? ''}${values[field.name].trim()}` : '—',
  }));

  return (
    <form
      onSubmit={handleSubmit}
      noValidate
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '24px',
        maxWidth: '520px',
        fontFamily: 'var(--jx-font-sans)',
        color: 'var(--jx-text)',
      }}
    >
      <JxStepper steps={[{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }]} current={step} />

      {isLast ? (
        <dl
          style={{
            display: 'grid',
            gridTemplateColumns: 'minmax(120px, auto) 1fr',
            gap: '12px 16px',
            margin: 0,
            padding: '16px',
            background: 'var(--jx-surface-2)',
            border: '1px solid var(--jx-border)',
            borderRadius: 'var(--jx-r)',
          }}
        >
          {reviewRows.map((row) => (
            <React.Fragment key={row.label}>
              <dt style={{ color: 'var(--jx-text-2)' }}>{row.label}</dt>
              <dd style={{ margin: 0, overflowWrap: 'anywhere' }}>{row.value}</dd>
            </React.Fragment>
          ))}
        </dl>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
          {STEP_FIELDS[step].map((field) => (
            <JxInputField
              key={field.name}
              label={field.label}
              type={field.type}
              prefix={field.prefix}
              helperText={field.helperText}
              required
              value={values[field.name]}
              onChange={change(field.name)}
              errorText={showErrors ? stepErrors[field.name] : undefined}
              disabled={submitting}
            />
          ))}
        </div>
      )}

      {submitError ? (
        <p role="alert" style={{ margin: 0, color: 'var(--jx-danger)' }}>
          {submitError}
        </p>
      ) : null}

      <div style={{ display: 'flex', gap: '8px', justifyContent: 'flex-end' }}>
        <JxButton variant="ghost" type="button" onClick={goBack} disabled={step === 0 || submitting}>
          Назад
        </JxButton>
        <JxButton variant="primary" type="submit" disabled={submitting}>
          {isLast ? (submitting ? 'Отправляем…' : 'Отправить') : 'Дальше'}
        </JxButton>
      </div>
    </form>
  );
}

